-- Isolated fictional customers; all data rolls back. No Horizonte mutations.
begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
create function pg_temp.id(n integer) returns uuid language sql immutable as $$select ('4d8a0000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create temp table saved(k text primary key,v jsonb);grant all on saved to authenticated,anon,service_role;
create temp table fixture as select pg_temp.id(5) uid,pg_temp.id(900) sid;
insert into auth.users(id,aud,role,email,email_confirmed_at,encrypted_password) values(pg_temp.id(5),'authenticated','authenticated','act-4d8-operator@example.invalid',clock_timestamp(),'synthetic');
insert into persons(id,auth_user_id,display_name) values(pg_temp.id(6),pg_temp.id(5),'Fictional Activation Operator');
insert into pikas_private.platform_memberships(person_id,role_code) values(pg_temp.id(6),'platform_admin');
insert into pikas_private.platform_team_handles(person_id) values(pg_temp.id(6));
insert into auth.sessions(id,user_id,created_at,updated_at) select sid,uid,clock_timestamp(),clock_timestamp() from fixture;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true) from fixture;
select public.pikas_session_start();
create function pg_temp.s(k text) returns text language sql as $$select v#>>'{}' from saved where saved.k=$1$$;
set local role authenticated;
insert into saved values('tenant',platform_provision_tenant(pg_temp.id(100),'ACT-4D8-A','Fictional Activation A','ACT-SCHOOL','Fictional School','America/Santo_Domingo','ACT-LOCATION','Fictional Location','ACT-CAFE','Fictional Cafe'));
insert into saved values('account',to_jsonb((select v->>'account_id' from saved where k='tenant')));
insert into saved values('intent',to_jsonb(platform_prepare_customer_admin(pg_temp.id(101),pg_temp.s('account')::uuid,'account',null,null,'account_admin','act-4d8-new@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
select is(platform_customer_activation_status(pg_temp.s('intent')::uuid)->>'identity_state','missing','fresh identity missing');
insert into saved values('reservation',platform_prepare_customer_activation(pg_temp.s('intent')::uuid));
insert into saved values('handle',to_jsonb((select v->>'handle' from saved where k='reservation')));
select is((select v->>'status' from saved where k='reservation'),'prepared','exact initial intent reserved');
select throws_ok($$select platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Fictional Admin')$$,'23514','confirmed_identity_pending','no Auth identity cannot complete');
reset role;
select ok(not has_function_privilege('service_role','public.platform_prepare_customer_activation(uuid)','execute'),'service cannot substitute real issuer');
select ok(not has_function_privilege('anon','public.platform_customer_activation_status(uuid)','execute'),'anonymous cannot inspect readiness');
select ok(not has_function_privilege('authenticated','pikas_private.customer_activation_state(uuid)','execute'),'private identity eligibility hidden');
select is((select count(*) from persons where auth_user_id=pg_temp.id(2)),0::bigint,'issuance has zero Person');
select ok((select ai.expires_at<=i.expires_at and ai.expires_at<=ai.created_at+interval '1 hour' from pikas_private.account_activation_invitations ai join pikas_private.account_activation_flows f on f.id=ai.flow_id join pikas_private.platform_customer_admin_intents i on i.id::text=f.source_handle where ai.handle=pg_temp.s('handle')),'link deadline bounded by hour and source');
-- Simulate successful Auth create with response lost before UUID recording.
insert into auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data)
 select pg_temp.id(2),'authenticated','authenticated',email_key,'synthetic-baseline',jsonb_build_object('pikas_activation_owner',owner_key) from pikas_private.account_activation_flows where source_handle=pg_temp.s('intent');
set local role authenticated;
select lives_ok($$select platform_bind_customer_activation(pg_temp.s('intent')::uuid,pg_temp.s('handle'),repeat('a',64))$$,'lost create reconciles exact owned UUID');
select lives_ok($$select platform_bind_customer_activation(pg_temp.s('intent')::uuid,pg_temp.s('handle'),repeat('a',64))$$,'exact bind retry idempotent');
select throws_ok($$select platform_bind_customer_activation(pg_temp.s('intent')::uuid,pg_temp.s('handle'),repeat('b',64))$$,'42501','invitation_unavailable','different digest same handle rejected');
select is(platform_customer_activation_status(pg_temp.s('intent')::uuid)->>'identity_state','activation_pending','owned identity awaits activation');
reset role;
select is((select count(*) from pikas_private.account_activation_events where invitation_handle=pg_temp.s('handle') and action='bound'),1::bigint,'bind audit once');
select is((select count(*) from persons where auth_user_id=pg_temp.id(2)),0::bigint,'binding grants zero Person/membership');
select ok(not exists(select 1 from pikas_private.account_activation_invitations where to_jsonb(account_activation_invitations)::text like '%/activar#token=%'),'no plaintext link persistence');
-- Replacement preserves ownership and source; previous credential revoked.
set local role authenticated;
insert into saved values('replacement',to_jsonb(platform_prepare_customer_activation(pg_temp.s('intent')::uuid)->>'handle'));
select lives_ok($$select platform_bind_customer_activation(pg_temp.s('intent')::uuid,pg_temp.s('replacement'),repeat('c',64))$$,'same source replacement binds');
select is(activation_preview(repeat('a',64)),null::jsonb,'old link unusable after replacement');
reset role;
select is((select count(*) from auth.users where email='act-4d8-new@example.invalid'),1::bigint,'one owned identity after reissue');
update auth.users set email_confirmed_at=clock_timestamp() where id=pg_temp.id(2);
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(2),'role','authenticated')::text,true);
set local role authenticated;
select lives_ok($$select activation_consume(repeat('c',64))$$,'existing recipient consume reused');
select lives_ok($$select activation_consume(repeat('c',64))$$,'lost consume response safely retries');
select is(activation_password_status(pg_temp.s('replacement')),'pending','confirmation before password is not ready');
select lives_ok($$select activation_claim_password(pg_temp.s('replacement'),repeat('d',64))$$,'existing immutable password claim reused');
select throws_ok($$select activation_claim_password(pg_temp.s('replacement'),repeat('e',64))$$,'42501','same_password_required','uncertain password cannot change payload');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true) from fixture;
set local role authenticated;
select throws_ok($$select platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Fictional Admin')$$,'23514','activation_password_pending','email confirmation alone cannot grant account_admin');
reset role;
select is((select count(*) from persons where auth_user_id=pg_temp.id(2)),0::bigint,'early denied completion leaves zero Person');
-- Simulate successful first password and lost finalize response (ready_at stays null).
update auth.users set encrypted_password='synthetic-new-password' where id=pg_temp.id(2);
set local role authenticated;
select is(platform_customer_activation_status(pg_temp.s('intent')::uuid)->>'identity_state','ready','actual hash change recovers lost finalize');
insert into saved values('completion',platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Fictional Admin'));
select is(platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Fictional Admin'),(select v from saved where k='completion'),'lost completion response exact receipt retry');
select throws_ok($$select platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Different Name')$$,'23505','platform_request_conflict','changed completion request fails closed');
reset role;
select is((select count(*) from account_memberships where account_id=pg_temp.s('account')::uuid and role_code='account_admin'),1::bigint,'exact account_admin granted once');
select is((select count(*) from school_memberships where person_id=((select v->>'person_id' from saved where k='completion'))::uuid),0::bigint,'no school role added');
select is((select status from pikas_private.platform_customer_admin_intents where id=pg_temp.s('intent')::uuid),'granted','exact source completed');
-- Eligible existing identity: no issuance, no new provenance, no password changes.
insert into accounts(id,code,name,tenant_kind) values(pg_temp.id(200),'ACT-4D8-EXIST','Fictional Existing','customer'),(pg_temp.id(201),'ACT-4D8-OTHER','Fictional Other','customer');
insert into auth.users(id,aud,role,email,email_confirmed_at,encrypted_password,raw_app_meta_data) values(pg_temp.id(3),'authenticated','authenticated','act-4d8-existing@example.invalid',clock_timestamp(),'existing-password','{}'),(pg_temp.id(4),'authenticated','authenticated','act-4d8-unconfirmed@example.invalid',null,'unchanged','{}');
set local role authenticated;
insert into saved values('existing',to_jsonb(platform_prepare_customer_admin(pg_temp.id(202),pg_temp.id(200),'account',null,null,'account_admin','act-4d8-existing@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
select is(platform_customer_activation_status(pg_temp.s('existing')::uuid)->>'identity_state','ready','confirmed existing identity ready');
select is(platform_prepare_customer_activation(pg_temp.s('existing')::uuid),'{"status":"identity_ready"}'::jsonb,'existing ready identity receives no link');
select lives_ok($$select platform_complete_initial_customer_admin(pg_temp.id(203),pg_temp.s('existing')::uuid,'Existing Admin')$$,'explicit completion existing eligible identity works');
reset role;
select is((select encrypted_password from auth.users where id=pg_temp.id(3)),'existing-password','existing password unchanged');
select is((select count(*) from pikas_private.account_activation_flows where source_handle=pg_temp.s('existing')),0::bigint,'no arbitrary adoption flow');
set local role authenticated;
insert into saved values('unconfirmed',to_jsonb(platform_prepare_customer_admin(pg_temp.id(204),pg_temp.id(201),'account',null,null,'account_admin','act-4d8-unconfirmed@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
select throws_ok($$select platform_prepare_customer_activation(pg_temp.s('unconfirmed')::uuid)$$,'42501','activation_identity_unavailable','unrelated unconfirmed identity never adopted');
select throws_ok($$select platform_bind_customer_activation(pg_temp.s('unconfirmed')::uuid,pg_temp.s('replacement'),repeat('f',64))$$,'42501','invitation_unavailable','cross-intent handle denied');
reset role;
update pikas_private.platform_customer_admin_intents set status='revoked' where id=pg_temp.s('unconfirmed')::uuid;
set local role authenticated;
select throws_ok($$select platform_prepare_customer_activation(pg_temp.s('unconfirmed')::uuid)$$,'42501','pending_intent_required','revoked source denied');
reset role;
-- Wrong source kind, issuer and expired-source recovery are fail-closed.
set local role authenticated;
insert into saved values('school_intent',to_jsonb(platform_prepare_customer_admin(pg_temp.id(205),pg_temp.s('account')::uuid,'school',(select (v->>'school_id')::uuid from saved where k='tenant'),null,'school_admin','act-4d8-school@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
select throws_ok($$select platform_prepare_customer_activation(pg_temp.s('school_intent')::uuid)$$,'42501','pending_intent_required','school source cannot use initial account-admin issuer');
insert into saved values('issuer_intent',to_jsonb(platform_prepare_customer_admin(pg_temp.id(206),pg_temp.id(201),'account',null,null,'account_admin','act-4d8-issuer@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
insert into saved values('issuer_handle',to_jsonb(platform_prepare_customer_activation(pg_temp.s('issuer_intent')::uuid)->>'handle'));
reset role;
insert into auth.users(id,aud,role,email,email_confirmed_at,encrypted_password) values(pg_temp.id(7),'authenticated','authenticated','act-4d8-other-operator@example.invalid',clock_timestamp(),'synthetic');
insert into persons(id,auth_user_id,display_name) values(pg_temp.id(8),pg_temp.id(7),'Fictional Other Operator');
insert into pikas_private.platform_memberships(person_id,role_code) values(pg_temp.id(8),'platform_admin');
insert into auth.sessions(id,user_id,created_at,updated_at) values(pg_temp.id(901),pg_temp.id(7),clock_timestamp(),clock_timestamp());
select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.id(7),'role','authenticated','session_id',pg_temp.id(901))::text,true);
select public.pikas_session_start();
set local role authenticated;
select throws_ok($$select platform_bind_customer_activation(pg_temp.s('issuer_intent')::uuid,pg_temp.s('issuer_handle'),repeat('f',64))$$,'42501','invitation_unavailable','another authorized operator cannot bind reserved invitation');
reset role;
select set_config('request.jwt.claims',jsonb_build_object('sub',uid,'role','authenticated','session_id',sid)::text,true) from fixture;
set local role authenticated;
insert into saved values('expiry_intent',to_jsonb(platform_prepare_customer_admin(pg_temp.id(207),pg_temp.id(201),'account',null,null,'account_admin','act-4d8-expired@example.invalid',clock_timestamp()+interval '1 second')->>'intent_id'));
insert into saved values('expiry_handle',to_jsonb(platform_prepare_customer_activation(pg_temp.s('expiry_intent')::uuid)->>'handle'));
reset role;
insert into auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data)
 select pg_temp.id(9),'authenticated','authenticated',email_key,'expired-baseline',jsonb_build_object('pikas_activation_owner',owner_key) from pikas_private.account_activation_flows where source_handle=pg_temp.s('expiry_intent');
set local role authenticated;
select platform_bind_customer_activation(pg_temp.s('expiry_intent')::uuid,pg_temp.s('expiry_handle'),repeat('e',64));
select pg_sleep(1.1);
select throws_ok($$select platform_prepare_customer_activation(pg_temp.s('expiry_intent')::uuid)$$,'42501','pending_intent_required','expired prepared source denied');
select is(activation_preview(repeat('e',64)),null::jsonb,'source expiry invalidates activation credential');
insert into saved values('new_expiry_intent',to_jsonb(platform_prepare_customer_admin(pg_temp.id(208),pg_temp.id(201),'account',null,null,'account_admin','act-4d8-expired@example.invalid',clock_timestamp()+interval '7 days')->>'intent_id'));
select throws_ok($$select platform_prepare_customer_activation(pg_temp.s('new_expiry_intent')::uuid)$$,'42501','activation_identity_unavailable','unfinished expired-source identity not reassociated');
-- Existing platform-team activation objects and issuance remain usable.
select platform_team_command(pg_temp.id(209),'prepare','{"name":"Fictional Team","email":"act-4d8-team@example.invalid","demo":false}');
insert into saved select 'team_handle',to_jsonb(platform_prepare_activation(item->>'handle')->>'handle') from jsonb_array_elements(platform_team_read()->'prepared') item where item->>'email'='act-4d8-team@example.invalid';
select throws_ok($$select platform_bind_customer_activation(pg_temp.s('issuer_intent')::uuid,pg_temp.s('team_handle'),repeat('f',64))$$,'42501','invitation_unavailable','platform-team handle cannot bind to customer source');
reset role;
insert into auth.users(id,aud,role,email,encrypted_password,raw_app_meta_data)
 select pg_temp.id(10),'authenticated','authenticated',email_key,'team-baseline',jsonb_build_object('pikas_activation_owner',owner_key) from pikas_private.account_activation_flows where source_kind='platform_team' and email_key='act-4d8-team@example.invalid';
set local role authenticated;
select lives_ok($$select platform_bind_activation(pg_temp.s('team_handle'),repeat('f',64))$$,'unchanged platform-team binding works');
reset role;
update pikas_private.application_sessions set started_at=clock_timestamp()-interval '1 hour',last_active_at=clock_timestamp()-interval '31 minutes' where session_id=(select sid from fixture);
set local role authenticated;
select throws_ok($$select platform_complete_initial_customer_admin(pg_temp.id(102),pg_temp.s('intent')::uuid,'Fictional Admin')$$,'42501','application_session_expired','expired operator session denies even completed replay');
select throws_ok($$select platform_customer_activation_status(pg_temp.s('existing')::uuid)$$,'42501','application_session_expired','expired session denies readiness');
select * from finish();
rollback;
